const Topbar = () => {
    const user = JSON.parse(localStorage.getItem('user'));
    return (
        <div className="bg-white p-4 flex justify-end items-center shadow ml-[220px]">
            <span className="mr-4 text-gray-600">{user?.email}</span>
            <span className="bg-blue-600 text-white rounded-full px-3 py-1">{user?.name?.[0]}</span>
        </div>
    );
};
export default Topbar;
